# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GERÇEK YAŞAM PROBLEMLERİNİ ÇÖZME AŞAMALARI (MAT.5.1.2)</text>\n  <rect x="18" y="48" width="155" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="95" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Problemi Anlama</text>\n  <text x="95" y="100" text-anchor="middle" font-size="11" fill="#1e3a8a">• Verilen sayıları ve</text>\n  <text x="95" y="118" text-anchor="middle" font-size="11" fill="#1e3a8a">birimleri belirle.</text>\n  <text x="95" y="144" text-anchor="middle" font-size="11" fill="#1e3a8a">• İstenen niceliği kendi</text>\n  <text x="95" y="162" text-anchor="middle" font-size="11" fill="#1e3a8a">cümlelerinle ifade et.</text>\n  <text x="95" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Şema / Tablo çiz!</text>\n\n  <rect x="186" y="48" width="155" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="263" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Strateji ve Tahmin</text>\n  <text x="263" y="100" text-anchor="middle" font-size="11" fill="#14532d">• Hangi işlemlerin hangi</text>\n  <text x="263" y="118" text-anchor="middle" font-size="11" fill="#14532d">sırayla yapılacağını seç.</text>\n  <text x="263" y="144" text-anchor="middle" font-size="11" fill="#14532d">• Yuvarlama ile sonucu</text>\n  <text x="263" y="162" text-anchor="middle" font-size="11" fill="#14532d">önceden tahmin et.</text>\n  <text x="263" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Planını oluştur!</text>\n\n  <rect x="354" y="48" width="155" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="431" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">3. Planı Uygulama</text>\n  <text x="431" y="100" text-anchor="middle" font-size="11" fill="#78350f">• Çok adımlı işlemleri</text>\n  <text x="431" y="118" text-anchor="middle" font-size="11" fill="#78350f">adım adım gerçekleştir.</text>\n  <text x="431" y="144" text-anchor="middle" font-size="11" fill="#78350f">• Ara sonuçların birimini</text>\n  <text x="431" y="162" text-anchor="middle" font-size="11" fill="#78350f">yanına mutlaka yaz.</text>\n  <text x="431" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">İşlemleri çöz!</text>\n\n  <rect x="522" y="48" width="160" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="602" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">4. Kontrol ve Genelleme</text>\n  <text x="602" y="100" text-anchor="middle" font-size="11" fill="#581c87">• Sonucu tahmininle ve</text>\n  <text x="602" y="118" text-anchor="middle" font-size="11" fill="#581c87">ters işlemle doğrula.</text>\n  <text x="602" y="144" text-anchor="middle" font-size="11" fill="#581c87">• Kısa yolları değerlendir,</text>\n  <text x="602" y="162" text-anchor="middle" font-size="11" fill="#581c87">benzer soruya genelle.</text>\n  <text x="602" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7e22ce">Doğruluğu sına!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BÖLME İŞLEMİNDE KALANIN GERÇEK YAŞAM BAĞLAMINDA YORUMLANMASI</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Kalanın İhmal Edilmesi</text>\n  <text x="125" y="100" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• «En fazla kaç tam paket /</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11.5" fill="#1e3a8a">ürün alınabilir?» sorularında</text>\n  <text x="125" y="136" text-anchor="middle" font-size="11.5" fill="#1e3a8a">kalan tek başına yetmez.</text>\n  <text x="125" y="164" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">Örnek: 145 TL ile 20 TL\'lik</text>\n  <text x="125" y="182" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">kalemden en çok 7 tane alınır</text>\n  <text x="125" y="200" text-anchor="middle" font-size="11" fill="#334155">(Artan 5 TL yeni kaleme yetmez).</text>\n  <text x="125" y="224" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">Cevap = Bölüm (7)</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Bölüme 1 Eklenmesi</text>\n  <text x="350" y="100" text-anchor="middle" font-size="11.5" fill="#14532d">• «Herkesin taşınması / tüm</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11.5" fill="#14532d">ürünün kolilenmesi için en az</text>\n  <text x="350" y="136" text-anchor="middle" font-size="11.5" fill="#14532d">kaç araç/koli gerekir?»</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">Örnek: 145 izci 20 kişilik</text>\n  <text x="350" y="182" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">minibüslere → 7 + 1 = 8 araç</text>\n  <text x="350" y="200" text-anchor="middle" font-size="11" fill="#334155">(Artan 5 izci için 1 araç daha).</text>\n  <text x="350" y="224" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">Cevap = Bölüm + 1 (8)</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">3. Doğrudan Kalanı Sorma</text>\n  <text x="575" y="100" text-anchor="middle" font-size="11.5" fill="#78350f">• «Geriye kaç TL / kaç adet</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11.5" fill="#78350f">artar?» veya «Tam dolması</text>\n  <text x="575" y="136" text-anchor="middle" font-size="11.5" fill="#78350f">için kaç tane daha gerekir?»</text>\n  <text x="575" y="164" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">Örnek: 145 ÷ 20 işleminde</text>\n  <text x="575" y="182" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">artan miktar 5\'tir; tam grup</text>\n  <text x="575" y="200" text-anchor="middle" font-size="11" fill="#475569">için 20 - 5 = 15 adet daha gerekir.</text>\n  <text x="575" y="224" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">Cevap = Kalan veya (Bölen - Kalan)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KAT ŞEMASI (KUTU MODELİ) VE ÇOK ADIMLI ÇÖZÜM STRATEJİLERİ</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Kat ve Fazlalık Problemleri (Kutu Modeli)</text>\n  <text x="70" y="105" font-size="12" font-weight="bold" fill="#831843">1. Sayı:</text>\n  <rect x="125" y="90" width="40" height="22" fill="#fbcfe8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="70" y="137" font-size="12" font-weight="bold" fill="#831843">2. Sayı:</text>\n  <rect x="125" y="122" width="40" height="22" fill="#fbcfe8" stroke="#db2777" stroke-width="1.5"/>\n  <rect x="170" y="122" width="40" height="22" fill="#fbcfe8" stroke="#db2777" stroke-width="1.5"/>\n  <rect x="215" y="122" width="40" height="22" fill="#fbcfe8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="275" y="138" font-size="12" font-weight="bold" fill="#831843">+ 20 (Toplam = 180)</text>\n  <text x="180" y="172" text-anchor="middle" font-size="11.5" fill="#831843">• Önce fazlalık çıkarılır: 180 - 20 = 160</text>\n  <text x="180" y="194" text-anchor="middle" font-size="11.5" fill="#831843">• Toplam kutu (1 + 3 = 4 kat): 160 ÷ 4 = 40 (Küçük sayı)</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#be185d">• Büyük sayı: (40 × 3) + 20 = 140</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Tersinden Çalışma ve Bütünden Parçaya</text>\n  <text x="520" y="102" text-anchor="middle" font-size="11.5" fill="#155e75">• Son durumu verilen problemlerde sondan</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11.5" fill="#155e75">başa doğru ters işlemler yapılır:</text>\n  <text x="520" y="146" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#164e63">(+) yerine (-), (×) yerine (÷) uygulanır.</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11.5" fill="#155e75">• Taksit / Birikim Problemlerinde:</text>\n  <text x="520" y="194" text-anchor="middle" font-size="11.5" fill="#155e75">Kalan Borç = Toplam Fiyat - Peşinat</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0e7490">Bir Taksit = Kalan Borç ÷ Taksit Sayısı</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
